// Original procedural model, generated by blender/render_demo.py.
export const BUILTIN_FIGURES=[{id:'orbit-sculpture',name:'轨道雕塑',fullName:'Orbit / 01',label:'轨道雕塑',
  number:'01',series:'原创几何收藏',role:'桌面雕塑',origin:'HAO',voice:'—',bio:'由圆环、球体和石质底座组成的原创参数化雕塑。可以自由替换成自己的 GLB。',
  src:'/assets/collectibles/models/orbit.glb',builtin:true,pedestal:false,availability:'local',
  author:'Hao-moon',authorUrl:'https://github.com/Hao-moon/hao-treehole',license:'https://opensource.org/license/mit',licenseLabel:'MIT',modelNote:'本项目原创演示资产'}];
export const SELECTION_KEY='hao-treehole-figure-v1';
const DATABASE='hao-treehole-figures';
export function validateGLB(buffer){
  if(buffer.byteLength<20||buffer.byteLength>40*1024*1024)throw new Error('请选择小于 40 兆的 GLB 模型');
  const v=new DataView(buffer);
  if(v.getUint32(0,true)!==0x46546c67||v.getUint32(4,true)!==2||v.getUint32(8,true)!==buffer.byteLength)throw new Error('模型格式不正确，请使用 GLB 2.0 文件');
  const size=v.getUint32(12,true);
  if(v.getUint32(16,true)!==0x4e4f534a||size>buffer.byteLength-20)throw new Error('模型文件不完整');
  let json;try{json=JSON.parse(new TextDecoder().decode(new Uint8Array(buffer,20,size)));}catch{throw new Error('模型文件无法读取');}
  if(!json.meshes?.length)throw new Error('文件中没有可展示的模型');
  if([...(json.images||[]),...(json.buffers||[])].some(i=>i.uri&&!i.uri.startsWith('data:')))throw new Error('请先将贴图打包进 GLB，再导入');
  if((json.extensionsRequired||[]).some(e=>['KHR_draco_mesh_compression','EXT_meshopt_compression','KHR_texture_basisu'].includes(e)))throw new Error('请下载未压缩的 GLB 版本再导入');
  return json;
}
function database(){return new Promise((resolve,reject)=>{const request=indexedDB.open(DATABASE,1);request.onupgradeneeded=()=>request.result.createObjectStore('models',{keyPath:'id'});request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});}
async function stored(mode,fn){const db=await database();return new Promise((resolve,reject)=>{const tx=db.transaction('models',mode),request=fn(tx.objectStore('models'));tx.oncomplete=()=>{db.close();resolve(request.result);};tx.onabort=tx.onerror=()=>{db.close();reject(tx.error||new Error('未能保存模型'));};});}
export function createFigureLibrary(){
  let models=[...BUILTIN_FIGURES],selected=models[0].id;const listeners=new Set();
  const get=()=>models.find(m=>m.id===selected)||models[0];
  const emit=()=>listeners.forEach(fn=>fn(get()));
  return {
    current:get,list:()=>[...models],subscribe(fn){listeners.add(fn);return ()=>listeners.delete(fn);},
    async init(){
      try{const entries=await stored('readonly',s=>s.getAll());models.push(...entries.map(e=>({...e,src:URL.createObjectURL(e.blob)})));}catch{}
      try{const saved=localStorage.getItem(SELECTION_KEY);if(models.some(m=>m.id===saved&&m.src))selected=saved;}catch{}
      return get();
    },
    select(id){const entry=models.find(m=>m.id===id);if(!entry)throw new Error('这件手办没有找到');if(!entry.src)throw new Error('这件手办尚未导入本地，暂不能摆上桌面');selected=id;try{localStorage.setItem(SELECTION_KEY,id);}catch{}emit();return get();},
    async add(file,values={}){
      const buffer=await file.arrayBuffer();validateGLB(buffer);
      const name=(values.name||file.name.replace(/\.glb$/i,'')).trim().slice(0,60)||'我的手办';
      const entry={id:crypto.randomUUID(),name,fullName:name,label:name,note:'本地收藏',series:values.series?.trim().slice(0,60)||'我的收藏',number:'藏',role:'个人收藏',bio:values.bio?.trim().slice(0,400)||'',blob:new Blob([buffer],{type:'model/gltf-binary'}),builtin:false};
      await stored('readwrite',s=>s.put(entry));const model={...entry,src:URL.createObjectURL(entry.blob)};models.push(model);return model;
    }
  };
}
